    state.li = li;
    state.startY = e.clientY;
    state.dy = 0;
    li.classList.add('is-dragging');
    ul.classList.add('is-reordering');
    try { li.setPointerCapture(e.pointerId); } catch (_) {}
  });

  ul.addEventListener('pointermove', (e) => {
    if (!state.li) return;
    move(e.clientY);
