    if (!state.li) return;
    const li = state.li;
    state.li = null;
    li.classList.remove('is-dragging');
    ul.classList.remove('is-reordering');
    li.style.transform = '';
  };

  ul.addEventListener('pointerup', end);
  ul.addEventListener('pointercancel', end);

  const handleKey = (e) => { ... } // attach to li at build time? Attach at keydown on li during build

  function move(clientY) {
    const li = state.li;
    const dy = clientY - state.startY;
    state.dy = dy;
    li.style.transform = 'translateY(' + dy + 'px)';
    const h = li.offsetHeight;
    const center = li.offsetTop + dy + h / 2;
    const others = Array.from(ul.children).filter(x => x !== li);
    let desired = others.length;
    for (let i = 0; i < others.length; i++) {
      const c = others[i].offsetTop + others[i].offsetHeight / 2;
      if (center < c) { desired = i; break; }
    }
    const cur = Array.from(ul.children).indexOf(li);
    if (desired === cur) return;
    const before = others[desired];
    // FLIP
    const kids = Array.from(ul.children);
    const rects = new Map(kids.map(k => [k, { top: k.offsetTop, left: k.offsetLeft }]));
    if (desired < cur) ul.insertBefore(li, before);
    else ul.insertBefore(li, before ? before.nextElementSibling : null);
    // FLIP compensation for other elements
    for (const k of ul.children) {
      if (k === li) continue;
      const old = rects.get(k);
      const dTop = old.top - k.offsetTop;
      if (dTop) {
        animateShift(k, dTop);
      }
    }
    // keep the visual position
    state.dy = center - h / 2 - li.offsetTop;
    li.style.transform = 'translateY(' + state.dy + 'px)';
  }

  function animateShift(k, dTop) {
    k.style.transition = 'none';
    k.style.transform = 'translateY(' + dTop + 'px)';
    void k.offsetHeight;
    k.style.transition = 'transform 160ms ease';
    k.style.transform = '';
    const done = () => { k.style.transition = ''; k.removeEventListener('transitionend', done); };
    k.addEventListener('transitionend', done);
  }
}
