```js
function makeSortable(ul) {
  const isCoarse = () => matchMedia('(pointer: coarse)').matches;
  let li = null;        // current item
  let startY = 0;
  let dy = 0;           // displacement while dragging
  let moved = false;

  const onDown = (e) => {
    if (li) return;
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    const item = e.target.closest('.item');
    if (!item || item.parentElement !== ul) return;
    if (isCoarse() && !e.target.closest('.handle')) return;
    li = item;
    startY = e.clientY;
    dy = 0;
    moved = false;
    item.classList.add('is-dragging');
    try { item.setPointerCapture(e.pointerId); } catch {}
  };

  const onMove = (e) => {
    if (!li) return;
    const prev = dy;
    dy = e.clientY - startY;
    if (Math.abs(dy) > 0.5) moved = true;
    li.style.transform = 'translateY(' + dy + 'px)';
    reorder(li, dy);
  };

  const onUp = () => {
    if (!li) return;
    const el = li;
    li = null;
    el.classList.remove('is-dragging');
    el.style.transform = '';
  };

  function reorder(item, d) {
    const h = item.offsetHeight;
    const center = item.offsetTop + d + h / 2;
    const others = [...ul.children].filter(x => x !== item);
    let want = others.length;
    for (let k = 0; k < others.length; k++) {
      if (center < others[k].offsetTop + others[k].offsetHeight / 2) { want = k; break; }
    }
    const cur = [...ul.children].indexOf(item);
    if (want === cur) return;
    // FLIP: fix the other elements
    const before = new Map([...ul.children].map(x => [x, x.offsetTop]));
    ul.insertBefore(item, ul.children[want]);
    for (const k of ul.children) {
      if (k === item) continue;
      const delta = before.get(k) - k.offsetTop;
      if (!delta) continue;
      k.style.transition = 'none';
      k.style.transform = 'translateY(' + delta + 'px)';
      requestAnimationFrame(() => requestAnimationFrame(() => {
        k.style.transition = 'transform 150ms ease';
        k.style.transform = '';
        const done = () => { k.style.transition = ''; k.style.transform=''; k.removeEventListener('transitionend', done); };
        k.addEventListener('transitionend', done);
      }));
    }
    // Fix displacement so the item stays under the cursor
    d = center - h / 2 - item.offsetTop;
    item.style.transform = 'translateY(' + d + 'px)';
    return d;
  }
  ...
}
```

