let step = 0;
function setStep(n) { step = Math.max(0, Math.min(STEP_COUNT - 1, n)); render(); }

function render() {
  qsa(".tab", tabsEl).forEach((t, i) => {
    t.classList.toggle("is-active", i === step);
    t.setAttribute("aria-selected", i === step ? "true" : "false");
  });
  qsa(".pane", panesEl).forEach((p, i) => p.classList.toggle("is-active", i === step));
  $("#btn-prev").disabled = step === 0;
  $("#btn-next").hidden = step === STEP_COUNT - 1;
  $("#btn-finish").hidden = step !== STEP_COUNT - 1;
  $("#progressBar").style.width = ((step + 1) / STEP_COUNT) * 100 + "%";
}
