**Collect + score** (the original's exact algorithm):

```js
function collect() {
  const out = [];
  lists.forEach((ul, list) => {
    qsa("li", ul).forEach((li, pos) => out.push({ list, pos, type: li.dataset.type }));
  });
  return out;
}
function score(p) {
  const count = (arr, ch) => arr.reduce((a, v) => a + (v === ch ? 1 : 0), 0);
  const res = {};
  for (const ch of ["d","i","s","c"]) {
    let v = 0;
    p.forEach(x => { if (x.pos === 0) v += x.type === ch ? 1 : 0; if (x.pos === 3) v -= x.type === ch ? 1 : 0; });
    res[ch] = v;
  }
  return res;
}
```
